import { createServer } from 'dhcp';

const server = createServer({
    range: ['192.168.3.10', '192.168.3.99'],
    server: '192.168.3.1',
    router: ['192.168.3.1'],
    dns: ['1.1.1.1', '8.8.8.8'],
    netmask: '255.255.255.0',
    static: { '11:22:33:44:55:66': '192.168.3.100' },
    forceOptions: ['hostname'],
    hostname: (packet) => packet?.clientId === 'sensor' ? 'sensor.local' : 'device.local',
    logLevel: 'info',
});

server.on('bound', (leases) => console.log(leases));
server.on('poolExhausted', (error) => console.error(error.message));
server.listen();
